<?php
require_once '../includes/auth.php'; require_role('student'); require_once '../config/db.php'; require_once '../includes/academic.php';
$page_title='My Timetable'; $user=$_SESSION['username'];
$days=[1=>'Monday',2=>'Tuesday',3=>'Wednesday',4=>'Thursday',5=>'Friday',6=>'Saturday'];
$hours=[1=>['09:00','10:00'],2=>['10:15','11:15'],3=>['11:15','12:15'],4=>['13:45','14:45'],5=>['15:00','16:00']];
$academic=academic_context($conn,$user);$batchId=(int)($academic['batch_id']??0);$semester=(int)($academic['current_semester']??0);$grid=[];$batchName='Batch not assigned';
if($batchId){$batchName=($academic['batch_name']??'').' · '.($academic['course']??'').' · Semester '.$semester.' · Year '.($academic['current_year']??'-');$st=$conn->prepare("SELECT tt.*,t.name teacher_name FROM tbl_timetable tt JOIN tbl_trs t ON t.username=tt.teacher_username WHERE tt.batch_id=? AND tt.semester=? ORDER BY tt.day_of_week,tt.hour_no");$st->bind_param('ii',$batchId,$semester);$st->execute();$r=$st->get_result();while($x=$r->fetch_assoc())$grid[$x['day_of_week']][$x['hour_no']]=$x;}
require '../includes/header.php';
?>
<div class="glass-hero mb-4"><div><span class="eyebrow-dark">MY WEEK</span><h2>5-hour timetable</h2><p><?php echo e($batchName); ?> · progression is automatic from your batch admission year.</p></div><div class="hero-orb"><i class="fa-solid fa-calendar-week"></i></div></div>
<div class="hour-strip glass-card mb-4"><div><strong>Daily timings</strong><span class="small-muted">Fixed college schedule</span></div><div class="hour-chip"><b>H1</b> 09:00–10:00</div><div class="break-chip">Break · 10:00–10:15</div><div class="hour-chip"><b>H2</b> 10:15–11:15</div><div class="hour-chip"><b>H3</b> 11:15–12:15</div><div class="break-chip">Lunch · 12:15–13:45</div><div class="hour-chip"><b>H4</b> 13:45–14:45</div><div class="break-chip">Break · 14:45–15:00</div><div class="hour-chip"><b>H5</b> 15:00–16:00</div></div>
<div class="glass-card"><?php if(!$batchId): ?><div class="empty">Your batch has not been assigned by the administrator yet.</div><?php else: ?><div class="timetable-wrap"><table class="table timetable-table modern-timetable student-timetable"><thead><tr><th>Day</th><?php foreach($hours as $h=>$time): ?><th><span>Hour <?php echo $h; ?></span><small><?php echo $time[0].'–'.$time[1]; ?></small></th><?php endforeach; ?></tr></thead><tbody><?php foreach($days as $dn=>$day): ?><tr><th><?php echo $day; ?></th><?php for($h=1;$h<=5;$h++):$s=$grid[$dn][$h]??null; ?><td><?php if($s): ?><div class="tt-cell"><span class="tt-hour">H<?php echo $h; ?></span><strong><?php echo e($s['subject']); ?></strong><span><?php echo e($s['teacher_name']); ?></span><small><?php echo e(substr($s['start_time'],0,5)); ?>–<?php echo e(substr($s['end_time'],0,5)); ?></small></div><?php else: ?><span class="tt-empty">No class</span><?php endif; ?></td><?php endfor; ?></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div>
<?php require '../includes/footer.php'; ?>
